"""1330 (#11, ranged and item completion): Record-Coverage-v1318.ps1 with left-hand item cases under the product
controller on the current build. Each item is granted with the lab-only `coop_grant_item` (1214ck: pistol and crossbow
with six rounds, two traps, the Heart; grenade and potions since 1214au) and selected with the native equip; the
checkpoint reload after each case restores the inventory. The partner is checked from its presentation state:
- pistol, crossbow: draw (native equip), three shots (LT), the reloads they cause, holster (X held) and redraw; the
  partner must present the ranged action of that weapon (ranged weight > .5) through at least three variants and at
  least two shots (entries into the fire variant: 3 for the gun, 7 for the crossbow, which signals shots through its
  mechanism rather than the shot flag; 1330a counted distinct shot-flag values);
- grenade: cook (LT held) and throw; the partner must present the grenade through at least two variants;
- stunmine, springrazor: look down at the floor (pitch +50, positive is down; 1330a looked ahead and never placed) and place (LT); the partner must present the trap through at least two variants;
- heart: hold the Heart up (LT held) and lower it; the partner must present the Heart through at least two variants;
- health: drink a granted health elixir (`coop_use_item health`); the partner must present the use reach (hand to mouth).
Generated by make_coverage_v1330.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1318.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("[string]$Take='coverage-v1318c',[string]$Candidate='candidate-npc-combat-v1214cf',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('walk8','crouch8','sprint3','turns','startstop','stairs')",
    "[string]$Take='coverage-v1330a',[string]$Candidate='candidate-npc-combat-v1214ck',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('pistol','crossbow','grenade','stunmine','springrazor','heart','health')")
rep("# 1318 (#11, locomotion completion)", "# 1330 (#11, ranged and item completion): pistol, crossbow, grenade, stun mine, spring razor, Heart and health elixir\n# granted in product mode and used natively. Generated by make_coverage_v1330.py.\n# 1318 (#11, locomotion completion)")
rep("$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=23500;startstop=17500;stairs=17500}[$case]",
    "$caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=23500;startstop=17500;stairs=17500;pistol=15000;crossbow=15000;grenade=9500;stunmine=8500;springrazor=8500;heart=9500;health=7500}[$case]")
rep("""    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""",
    """    $itemPlans=@{
     pistol=@(@(800,'grant','pistol'),@(3000,'lt',250),@(4700,'lt',250),@(6400,'lt',250),@(8800,'x',1500),@(12000,'x',650));
     crossbow=@(@(800,'grant','crossbow'),@(3000,'lt',250),@(4700,'lt',250),@(6400,'lt',250),@(8800,'x',1500),@(12000,'x',650));
     grenade=@(@(800,'grant','grenade'),@(3000,'lt',1300));
     stunmine=@(@(800,'grant','stunmine'),@(2200,'pitch',50),@(3200,'lt',300),@(6200,'pitch',0));
     springrazor=@(@(800,'grant','springrazor'),@(2200,'pitch',50),@(3200,'lt',300),@(6200,'pitch',0));
     heart=@(@(800,'grant','heart'),@(3000,'lt',2200));
     health=@(@(800,'grant','health'),@(2500,'use','health'))}
    if($itemPlans.ContainsKey($case)){$ip=$itemPlans[$case]
     if($step-lt$ip.Count-and$t-ge$ip[$step][0]){$d=$ip[$step]
      switch($d[1]){'grant'{C $source "coop_grant_item $($d[2])"};'use'{C $source "coop_use_item $($d[2])"};'lt'{& "$lab/Send-D2Input.ps1" -Role $source -LeftTrigger 255 -DurationMs $d[2]|Out-Null};'x'{I $source X $d[2]};'pitch'{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $d[2] -Quick|Out-Null}}
      $segments.Add(@{ms=$t;item=$d[1];arg=$d[2]});$step++}}
    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""")
rep("""$samples.Add([pscustomobject]@{ms=$t;a=$mv.a;""",
    """$samples.Add([pscustomobject]@{ms=$t;rangedKind=$mv.rangedKind;rangedVariant=$mv.rangedVariant;rangedWeight=$mv.rangedWeight;rangedShot=$mv.rangedShot;rangedMechanism=$mv.rangedMechanism;grenadeHeld=$mv.grenadeHeld;grenadeVariant=$mv.grenadeVariant;grenadeWeight=$mv.grenadeWeight;trapHeld=$mv.trapHeld;trapVariant=$mv.trapVariant;trapWeight=$mv.trapWeight;trapStock=$mv.trapStock;heartHeld=$mv.heartHeld;heartVariant=$mv.heartVariant;heartWeight=$mv.heartWeight;a=$mv.a;""")
rep("""   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""",
    """   if($itemPlans.ContainsKey($case)){$row.grant=(S $source '.observer-camera.json').itemGrant;$row.use=(S $source '.observer-camera.json').itemUse
    function Shown($w,$v){@($samples|Where-Object {[double]$_.$w-gt.5}|ForEach-Object {[int]$_.$v}|Sort-Object -Unique)}
    switch($case){
     {$_-in'pistol','crossbow'}{$kind=if($case-eq'pistol'){1}else{2};$on=@($samples|Where-Object {[double]$_.rangedWeight-gt.5-and[int]$_.rangedKind-eq$kind});$row.rangedSamples=$on.Count
      $row.rangedVariants=@($on|ForEach-Object {[int]$_.rangedVariant}|Sort-Object -Unique);$row.shots=0;$pf=$false;foreach($x in $samples){$f=[int]$x.rangedVariant-in3,7-and[double]$x.rangedWeight-gt.5;if($f-and!$pf){$row.shots++};$pf=$f}
      if($on.Count-lt5-or@($row.rangedVariants).Count-lt3-or$row.shots-lt2){throw "$case presented $($on.Count) samples, variants $($row.rangedVariants-join ','), shots $($row.shots)"}
      $row.checks.Add("$case presented (kind $kind): variants $($row.rangedVariants-join ','), $($row.shots) shots")}
     'grenade'{$row.grenadeVariants=Shown 'grenadeWeight' 'grenadeVariant';if(@($row.grenadeVariants).Count-lt2){throw "Grenade variants $($row.grenadeVariants-join ',')"};$row.checks.Add("Grenade presented: variants $($row.grenadeVariants-join ',')")}
     {$_-in'stunmine','springrazor'}{$row.trapVariants=Shown 'trapWeight' 'trapVariant';if(@($row.trapVariants).Count-lt2){throw "$case variants $($row.trapVariants-join ',')"};$row.checks.Add("$case presented: variants $($row.trapVariants-join ',')")}
     'heart'{$row.heartVariants=Shown 'heartWeight' 'heartVariant';if(@($row.heartVariants).Count-lt2){throw "Heart variants $($row.heartVariants-join ',')"};$row.checks.Add("Heart presented: variants $($row.heartVariants-join ',')")}
     'health'{$u=@($samples|Where-Object {[double]$_.useWeight-gt.5});$row.useSamples=$u.Count;$row.useVariants=@($u|ForEach-Object {[int]$_.useVariant}|Sort-Object -Unique);if(!$u.Count){throw 'Elixir use reach not presented'};$row.checks.Add("Health elixir drink presented as the use reach ($($u.Count) samples)")}}}
   if($case-eq'stairs'){C $peer 'coop_observer_camera off'""")
rep("scope='Locomotion completion coverage (1318, #11): walks and crouch walks in 8 directions, sprint and diagonals, in-place turns by size, starts/stops and speed changes, stairs; both source roles, product controller, free camera; checked from the partner presentation state; fixture restored after every case.'",
    "scope='Ranged and item coverage (1330, #11): pistol and crossbow (draw, shots, reload, holster, redraw), grenade cook and throw, stun mine and spring razor placement, the Heart, the health elixir; granted in product mode (lab only), used natively; both source roles; checked from the partner presentation state; fixture restored after every case.'")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1330.ps1').write_bytes(out.encode('utf-8'))
print('ok')
